import torch
import torch.nn as nn


class TensorFunctorAttention(nn.Module):
    """Coordinate-free sequence mixing layer.

    The linear projection is applied along the channel axis wherever it lives
    in the tensor layout; every other axis is treated as an arbitrary batch of
    coordinates.  There are no Python loops, no hard-coded spatial sizes and no
    in-place index writes, so the module works for any input shape, inside
    `torch.vmap` (including nested vmap, which strips leading batch axes) and
    under autograd.
    """

    def __init__(self, dim: int = 16):
        super().__init__()
        self.dim = int(dim)
        self.proj = nn.Linear(self.dim, self.dim)

    def _channel_axis(self, x: torch.Tensor) -> int:
        """Locate the channel axis in a layout-independent way."""
        shape = tuple(x.shape)
        ndim = len(shape)
        dim = self.dim

        if ndim == 0:
            raise ValueError(
                f"TensorFunctorAttention expects at least a 1D input, got shape {shape}"
            )
        if ndim == 1:
            # Batch axis already stripped (nested vmap) or a bare (C,) tensor.
            return 0
        if ndim == 2:
            # (N, C) or (C, L) after one vmap level.
            if shape[1] == dim:
                return 1
            if shape[0] == dim:
                return 0
            return 1
        if ndim == 3:
            # (N, C, L) or (C, H, W) after one vmap level.
            if shape[1] == dim:
                return 1
            if shape[0] == dim:
                return 0
            if shape[2] == dim:
                return 2
            return 1
        # ndim >= 4: (N, C, H, W[, ...]) or channels-last (N, H, W, C).
        if shape[1] == dim:
            return 1
        if shape[-1] == dim:
            return ndim - 1
        return 1

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        axis = self._channel_axis(x)

        # Move the channel axis to the end, apply the linear map there, then
        # move it back.  All remaining axes flow through untouched.
        if axis == x.dim() - 1:
            return self.proj(x)

        moved = x.movedim(axis, -1)
        out = self.proj(moved)
        return out.movedim(-1, axis)

import torch
import torch.nn as nn


class MorphismEncoder(nn.Module):
    """Coordinate-free channel/feature mixing layer.

    The linear projection acts purely on the feature (``dim``) axis; every other
    axis (batch and any number of leading/trailing spatial or sequence axes) is
    carried through as an opaque batch dimension.  The forward pass therefore
    contains no Python loops, no in-place indexed writes and no hard-coded shape
    assumptions, so it composes cleanly with ``torch.vmap`` and with autograd,
    and keeps working when the sequence/spatial rank or size changes between
    training and evaluation.
    """

    def __init__(self, dim: int = 16):
        super().__init__()
        self.dim = dim
        self.proj = nn.Linear(dim, dim)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dim() <= 1:
            # Bare feature vector: (dim,)
            return self.proj(x)

        lead, last = x.shape[1], x.shape[-1]

        if x.dim() == 2 or (last == self.dim and lead != self.dim):
            # Channel-last / packed feature matrix: (N, dim) or (..., dim)
            return self.proj(x)

        if lead == self.dim:
            # Channel-first layout: (N, dim, *spatial) -> (N, *spatial, dim)
            return self.proj(x.movedim(1, -1)).movedim(-1, 1)

        if last == self.dim:
            # Ambiguous rank that still ends with the feature axis.
            return self.proj(x)

        raise ValueError(
            f"MorphismEncoder(dim={self.dim}) cannot locate a feature axis "
            f"of size {self.dim} in input of shape {tuple(x.shape)}."
        )
